public static void solve() {
    java.util.Scanner in = new java.util.Scanner(System.in);
    int H = in.nextInt();
    int height = 0;
    int growth = 1;
    int i = 0;

    while (true) {
        if (height > H) {
            System.out.print(i);
            return;
        }
        height = height + growth;
        growth = growth * 2;
        i++;
    }
}
